fn rolling_max(numbers: Vec<i32>) -> Vec<i32> {
    let mut result = Vec::with_capacity(numbers.len());

    let mut cur_max: Option<i32> = None;
    for x in numbers {
        cur_max = Some(match cur_max {
            None => x,
            Some(m) => if x > m { x } else { m },
        });
        result.push(cur_max.unwrap());
    }

    result
}